library_register_drm_tooltip: "Wie „Zum Startbildschirm hinzufügen“, patcht aber zuerst applicationDrmType der Quelle auf \"standard\" — die Quelldatei wird verändert. Nur verwenden, wenn das normale Hinzufügen mit einem DRM-Fehler scheitert.",
