saves_loading: "Speicherstände werden gelesen…",
saves_restore_confirm_body_v2: "Schließe zuerst das Spiel. Wähle eine .zip-Sicherung dieses Spiels, die von dieser PS5 und diesem Benutzer stammt. Der Spielstand auf der PS5 wird kopiert, dann ersetzt und zurückgelegt, falls die Wiederherstellung fehlschlägt. Diese Kopie bleibt danach nur, wenn unter Automatische Sicherungen ein Ordner oder Server eingestellt ist.",
