about_disclaimer_title: "Haftungsausschluss",
about_disclaimer_purpose: "ps5upload wird ausschließlich für Forschung, Bildung, Interoperabilität und die Entwicklung von Homebrew bereitgestellt. Es steht in keiner Verbindung zu Sony Interactive Entertainment Inc. und wird von dieser weder unterstützt noch gebilligt. „PlayStation“ und „PS5“ sind Marken von Sony Interactive Entertainment Inc. und werden hier nur zur Identifikation verwendet.",
about_disclaimer_piracy: "Verwenden Sie es nur mit Hardware, die Ihnen gehört, und mit Inhalten, die Sie rechtmäßig besitzen. Es darf nicht dazu verwendet werden, Software zu kopieren, zu verbreiten oder auszuführen, zu deren Nutzung Sie nicht berechtigt sind.",
about_disclaimer_risk: "Diese Software wird „wie besehen“ und ohne jegliche Gewährleistung bereitgestellt. Der Betrieb einer modifizierten Konsole kann sie dauerhaft beschädigen, Spielstände und Lizenzen unwiederbringlich zerstören und zur Sperrung Ihres Kontos oder Ihrer Konsole führen. Die Nutzung erfolgt vollständig auf eigene Gefahr und in eigener Verantwortung für die Folgen. Sichern Sie vorher alles, dessen Verlust Sie sich nicht leisten können.",
