"pkglib.auth.retail": "Retail",
"connection_prior_killed": "Der vorherige Helfer wurde nicht sauber beendet",
"connection_prior_killed_detail": "Das kann bedeuten, dass ein anderes Payload auf der Konsole ihn beendet hat, dem System der Speicher knapp wurde oder er abgestürzt ist. Die stderr.log in einem Fehlerbericht zeigt, was davon. Wenn du ps5upload über einen Autoloader lädst, versuche stattdessen, es von hier zu senden.",
