"pkglib.fpkgsupport.lead": "Ein PS5-Fake-Paket lässt sich nur installieren, wenn die Fake-Paket-Unterstützung bereits auf der Konsole geladen ist. Lade alle drei in dieser Reihenfolge, bevor du installierst:",
"pkglib.fpkgsupport.kstuff": "— die Version mit PS5-Fake-Paket-Unterstützung",
"pkglib.fpkgsupport.ppr": "— wendet den PPR-Klartext-/No-Auth-Patch an",
"pkglib.fpkgsupport.ppr_where": "Dafür gibt es keinen fertigen Download: Es wird aus dem Quellcode auf GitHub gebaut,",
"pkglib.fpkgsupport.smp": "— die Mount-Schicht, die den installierten Titel registriert",
"pkglib.fpkgsupport.tail": "Ohne sie lehnt die Konsole die Installation ab oder nimmt sie an und kann das Spiel dann nicht einhängen. Retail- und Debug-Pakete brauchen nichts davon – wenn du so eines installierst, ignoriere diesen Hinweis.",
