"power_wake_needs_awake": "Schalte die Konsole ein, um dies einzurichten – das Koppeln registriert über das Netzwerk und funktioniert daher nur, solange die Konsole wach ist. Du musst es nur einmal tun.",
"power_wake_ready_userselect": "Aufwecken ist eingerichtet – es endet beim Benutzerauswahlbildschirm",
