"backport_title": "Backport für {name}",
"backport_overlay_unavailable": "Bibliotheks-Overlay nicht verfügbar",
"backport_overlay_external": "Ein externes BackPork/unionfs-Overlay ist bereits aktiv.",
"backport_overlay_missing": "Sende das aktuelle ps5upload-Payload, bevor du einen Backport anwendest. Ältere Payloads können die gewählten Bibliotheken beim Spielstart nicht einhängen.",
"backport_failed": "Backport konnte nicht abgeschlossen werden",
"backport_inspecting": "Installierte Bibliotheksfamilien werden geprüft…",
"backport_summary": "Dadurch wird das Spiel auf das SDK-Paar von FW 4 herabgestuft und das Set mit {count} Bibliotheken installiert, das {set} mitbringt. Ein Set wird vollständig installiert – das Mischen von Bibliotheken verschiedener Spiele lässt einen Backport beim Start scheitern.",
"settings_card_fakelibs": "Backport-Bibliotheken",
"backport_verify_unpatched": "Dieser Titel ist nicht zurückportiert",
"backport_verify_unpatched_body": "Seine eboot trägt noch die ursprüngliche SDK-Version, daher kann er auf dieser Firmware nicht laufen, egal welche Bibliotheken installiert sind – das Bibliotheks-Set ist nicht das Problem. Führe den Backport erneut aus; passiert es wieder, greift der SDK-Patch nicht.",
"backport_no_larger": "Dieses Spiel braucht Bibliotheken, die keines deiner Sets hat. Importiere ein vollständigeres Paket oder scanne eine andere Konsole.",
"backport_verifying": "Starten und beobachten – ein fehlgeschlagener Start wird wiederholt, weil das Starten so unzuverlässig ist, dass ein einzelner Fehlschlag nichts beweist.",
"backport_verify_running": "Es läuft – kommt es bis ins Spiel?",
"backport_verify_running_body": "Das Spiel läuft nach einer Minute noch ({threads} Threads). Es ist also beim Laden nicht abgestürzt, aber das heißt nicht, dass es spielbar ist – sieh auf den Bildschirm. Behalte es, wenn es funktioniert, oder mach es rückgängig und probiere das nächste Set.",
"backport_verify_missing": "Es braucht weitere Bibliotheken",
"backport_verify_missing_body": "Das Spiel hat eine Funktion aufgerufen, die keine der installierten Bibliotheken bereitstellt. Noch {count} größere(s) Set(s) zum Probieren.",
"backport_verify_wrong": "Falsche Bibliotheken für dieses Spiel",
"backport_verify_wrong_body": "Dieser Titel ist korrekt gepatcht, ist mit diesen Bibliotheken aber nicht gestartet, also sind es nicht die, die er braucht. Noch {count} andere(s) Set(s) zum Probieren.",
"backport_verify_unknown": "Nicht feststellbar, ob es funktioniert hat",
"backport_verify_unknown_body": "Die Starts waren sich nicht einig, das sagt also nichts über die Bibliotheken – Starts scheitern oft genug von selbst, dass ein gemischtes Ergebnis bedeutungslos ist. Starte es selbst und mach es rückgängig, wenn es nicht spielbar ist.",
"backport_get_more": "Weitere Bibliotheken holen…",
"backport_needs_libraries": "Der Backport von {name} braucht Ersatz-Systembibliotheken. Das sind Sony-Dateien, die ps5upload nicht mitliefern kann – du stellst sie einmal aus Spielen bereit, die du besitzt, und jeder spätere Backport nutzt sie wieder.",
"fakelibs_action_failed": "Das hat nicht geklappt",
"fakelibs_empty": "Noch keine Bibliotheken. Backports brauchen Ersatz-Systembibliotheken – Sony-Dateien, die ps5upload nicht mitliefern kann, also stellst du sie einmal aus Spielen bereit, die du besitzt.",
