upload_warn_unsettled: "Jedes Byte ist auf der Konsole angekommen, sie hat aber noch nicht bestätigt, alle Dateien gespeichert zu haben. Sie werden von selbst fertig; fällt der Strom vorher aus, senden Sie den Ordner erneut.",
