queue_rar_password_retry: "Mit Passwort wiederholen",
"joberr.ava1_refused": "Die PS5 hat diese Anfrage abgelehnt (Code {code}). Versuche es erneut; tritt es wieder auf, aktualisiere Helfer und App auf dieselbe Version und gib den Code in einem Fehlerbericht an.",
"joberr.ava1_busy": "Der PS5-Helfer ist beschäftigt und hat diese Übertragung nicht rechtzeitig angenommen. Warte, bis seine andere Arbeit fertig ist, und klicke dann auf Wiederholen.",
"joberr.ava1_unreachable": "Die PS5 ist nicht erreichbar. Prüfe, ob sie eingeschaltet und im selben Netzwerk ist und der Helfer läuft, und klicke dann auf Wiederholen.",
"joberr.ava1_exists": "Das Ziel existiert bereits auf der PS5. Wähle Überschreiben, um es zu ersetzen, oder ein anderes Ziel.",
"joberr.ava1_path_link": "Ein Ordner im Ziel auf der PS5 ist eine Verknüpfung (symbolischer Link) oder eine Datei, daher schreibt PS5Upload nicht hindurch. Wähle ein anderes Ziel oder entferne dieses Element auf der PS5 und klicke dann auf „Erneut versuchen“.",
"joberr.ava1_local_path": "Ein Ordner im Download-Ordner auf diesem Computer ist eine Verknüpfung (symbolischer Link) oder eine Datei, daher schreibt PS5Upload nicht hindurch. Wähle einen anderen Ordner und klicke dann auf „Erneut versuchen“.",
"joberr.ava1_commit_exists": "Die Datei wurde hochgeladen, konnte aber nicht veröffentlicht werden, weil das Ziel bereits existiert. Wähle Überschreiben, um es zu ersetzen, oder ein anderes Ziel.",
"joberr.ava1_cross_device": "Das Ziel liegt auf einem anderen Laufwerk als der Zwischenspeicher, daher konnte die PS5 die Datei nicht verschieben. Wähle ein Ziel auf demselben Laufwerk oder lade zuerst auf das interne Laufwerk hoch.",
"joberr.ava1_wrong_console": "Das Gerät unter dieser Adresse ist nicht die PS5, mit der diese App gekoppelt wurde. Prüfe die Adresse oder koppele erneut mit dieser Konsole.",
"joberr.ava1_no_identity": "Diese App hat noch keine Kopplungsidentität. Koppele sie im Verbindungsbildschirm mit der PS5 und versuche es erneut.",
"joberr.zip_read_error": "Die .zip-Datei konnte nicht gelesen werden (Datei oder Laufwerk war womöglich plötzlich nicht mehr verfügbar). Prüfe, ob die Quelle noch verbunden ist, und klicke auf Wiederholen.",
"joberr.ava1_zip_corrupt": "Diese .zip-Datei konnte nicht gelesen werden: Sie ist beschädigt oder unvollständig. Lade sie erneut herunter oder erstelle sie neu und versuche es dann erneut.",
"joberr.ava1_7z_corrupt": "Diese .7z-Datei konnte nicht gelesen werden: Sie ist beschädigt oder unvollständig. Lade sie erneut herunter oder erstelle sie neu und versuche es dann erneut.",
"joberr.ava1_7z_encrypted": "Diese .7z-Datei ist verschlüsselt und kann nicht gestreamt werden. Entpacke sie auf deinem Computer und lade stattdessen den Ordner hoch.",
"joberr.ava1_7z_unsafe_path": "Diese .7z-Datei enthält einen unsicheren Dateipfad (er verlässt den eigenen Ordner). Entpacke sie auf deinem Computer und lade stattdessen den Ordner hoch.",
"joberr.tar_read_error": "Das Archiv konnte nicht gelesen werden (Datei oder Laufwerk war womöglich plötzlich nicht mehr verfügbar). Prüfe, ob die Quelle noch verbunden ist, und klicke auf Wiederholen.",
"joberr.ava1_tar_corrupt": "Dieses Archiv konnte nicht gelesen werden: Es ist beschädigt oder unvollständig. Lade es erneut herunter oder erstelle es neu und versuche es dann erneut.",
"joberr.ava1_tar_unsafe_path": "Dieses Archiv enthält einen unsicheren Dateipfad (er verlässt den eigenen Ordner). Entpacke es auf deinem Computer und lade stattdessen den Ordner hoch.",
"joberr.ava1_tar_unsupported": "Dieses Archiv enthält etwas, das der Upload nicht entpacken kann (eine Sparse-Datei, zwei Namen, die sich nur in der Groß-/Kleinschreibung unterscheiden, oder einen Teil eines mehrteiligen Tar-Archivs). Entpacke es auf deinem Computer und lade stattdessen den Ordner hoch.",
"joberr.ava1_tar_memory": "Dieses Archiv wurde mit einem größeren Speicherfenster (zstd --long) komprimiert, als dieses Gerät zum Entpacken erlaubt. Lade es von einem Computer mit mehr Arbeitsspeicher hoch oder komprimiere es ohne --long neu.",
"joberr.rar_password": "Diese .rar-Datei braucht ein Passwort, oder das eingegebene Passwort war falsch. Gib das richtige Passwort ein und versuche es erneut.",
"joberr.rar_corrupt": "Diese .rar-Datei ist beschädigt, oder Teile fehlen oder sind in falscher Reihenfolge. Stelle sicher, dass alle Teile vorhanden sind, und versuche es erneut.",
"joberr.ava1_copy_lost": "Die PS5 hat diesen Kopiervorgang aus den Augen verloren (Helfer neu gestartet oder Verbindung unterbrochen). Klicke auf Wiederholen, um ihn neu zu starten.",
"joberr.ava1_copy_failed": "Die PS5 konnte das Kopieren nicht abschließen. Prüfe den freien Speicher und ob Quelle und Ziel noch verfügbar sind, und versuche es erneut.",
"joberr.ava1_local_io": "Dieser Computer konnte die heruntergeladene Datei nicht schreiben. Prüfe Berechtigungen und freien Speicher des Zielordners und versuche es erneut.",
"joberr.ava1_bad_manifest": "Die PS5 hat eine Dateiliste gesendet, die diese App nicht versteht. Aktualisiere Helfer und App auf dieselbe Version und versuche es erneut.",
"joberr.helper_not_ava1": "Der PS5-Helfer läuft nicht. Sende ihn im Verbindungsbildschirm und versuche es erneut.",
"joberr.file_too_large": "Diese Datei ist zu groß für das Format des Ziellaufwerks: FAT32 fasst höchstens 4 GiB pro Datei. Verwende ein exFAT-Laufwerk oder den internen Speicher der PS5.",
"joberr.source_missing": "Der zu sendende Ordner ist nicht mehr da. Liegt er auf einem externen Laufwerk oder einer Freigabe, verbinde sie erneut und versuche es dann noch einmal.",
"joberr.source_read_failed": "Eine Datei konnte auf diesem Computer nicht gelesen werden. Liegt sie auf einem externen Laufwerk oder einer Freigabe, prüfe die Verbindung und versuche es erneut. Was die PS5 schon hat, bleibt erhalten.",
"joberr.not_paired": "Diese PS5 hat diese App noch nicht akzeptiert. Koppele beide (Schaltfläche Koppeln…) und versuche es erneut.",
"joberr.helper_starting": "Der PS5-Helfer startet noch. Warte einige Sekunden und versuche es erneut.",
"joberr.ava1_failed": "Der PS5-Helfer wurde gestartet, aber sein Übertragungsserver nicht. Starte die Konsole neu und versuche es erneut.",
"joberr.helper_not_running": "Auf der PS5 läuft kein Helfer. Sende ihn im Verbindungsbildschirm und versuche es erneut.",
