installed_launch_smp_refused: "Die PS5 hat den Start dieses Spiels verweigert (0x80940033), obwohl kstuff läuft. ShadowMount+ bindet ein Spiel beim Start ein, und das ist nicht passiert. Schließe ein laufendes Spiel, sende ShadowMount+ unter Payloads erneut und drücke dann auf Spielen.",
