kept_intro: "Die Ordner, die ps5upload selbst auf dieser Konsole anlegt, und wie viel jeder enthält. Temporäre Dateien und Testdateien können bereinigt werden; deine Pakete und Spielstand-Backups werden von hier nur geöffnet, nie gelöscht.",
