"share.send": "Senden",
"share.note.link": "Der Link wird unter „Von einem Link installieren“ eingetragen. Dort wählst du, wie er geladen wird, und startest die Installation.",
"share.note.package": "Das Paket wird an die PS5 gestreamt und installiert. Vorher wird nichts auf die PS5 kopiert.",
"share.note.archive": "Das Archiv wird unter „Pakete aus einem Archiv installieren“ geöffnet, wo die enthaltenen Pakete aufgelistet sind. Installiere sie von dort.",
"share.note.copy": "Nur die App, die sie geteilt hat, kann diese Datei lesen. Sie wird deshalb zuerst in diese App kopiert (bis {limit}).",
"share.copying": "Wird in die App kopiert…",
"share.no_link": "Im Geteilten wurde kein Link gefunden.",
"share.unsupported": "PS5Upload installiert .pkg- und .fpkg-Pakete sowie ZIP-, 7z- und RAR-Archive. Das hier ist nichts davon.",
"share.too_large": "Diese Datei ist größer als {limit} und zu groß, um sie in die App zu kopieren. Lade sie zuerst auf das Telefon herunter (zum Beispiel in „Download“) und teile sie dann erneut aus der Dateien-App.",
"share.no_space": "Auf dem Telefon ist nicht genug freier Speicher, um sie in die App zu kopieren.",
"share.copy_failed": "Die Datei konnte aus der App, die sie geteilt hat, nicht gelesen werden. Lade sie zuerst auf das Telefon herunter und teile sie dann erneut aus der Dateien-App.",
"share.remote_engine": "Diese App nutzt eine Engine auf einem anderen Computer, die keine Dateien auf diesem Gerät öffnen kann.",
"share.not_connected": "Verbinde dich zuerst mit einer PS5. Das hier wartet, bis du es sendest oder abbrichst.",
"install.description.v2": "Installiere .pkg- und .fpkg-Pakete auf deiner PS5: direkt von diesem Computer oder einem Link (Streamen & installieren) oder von einer Kopie, die zuerst auf die PS5 gelegt wird (Hochladen & installieren).",
