health_junk_explain_v2: "Dinge, die ps5upload angelegt hat und nicht mehr braucht: unfertige Dateien aus abgebrochenen Übertragungen, Paketkopien, die seit über einer Stunde im Temp-Ordner liegen, und alte Geschwindigkeitstest-Dateien. Es werden nur die eigenen Ordner von ps5upload durchsucht; deine Spiele, Pakete und Spielstände werden nie angerührt.",
