"speedtest.verdict.gigabit": "Das ist eine volle Gigabit-Verbindung: so schnell, wie der Netzwerkanschluss der PS5 kann.",
"speedtest.verdict.hundred": "Das sieht nach einer 100-Mbit-Verbindung aus, die bei etwa 11 MB/s endet. Prüfe das Kabel (Cat5e oder besser) und ob jeder Switch- oder Router-Port auf dem Weg Gigabit kann.",
"speedtest.verdict.mid": "Gut, aber unter dem, was ein Gigabit-Kabel schafft (90–115 MB/s). Übliche Ursachen: WLAN auf einer der beiden Seiten oder anderer Verkehr im Netzwerk.",
"speedtest.verdict.slow": "Langsam. Meist liegt es an schwachem WLAN, einem VPN oder einem ausgelasteten Netzwerk. Ein Netzwerkkabel zur PS5 behebt das.",
