"fpkg.save_to_ps5_unsupported": "Direkt auf die PS5 geht mit einem einfachen .exfat-, .ffpkg- oder .ffpfs-Image oder einem .exfat mit zstd-Packs. Speichere dieses auf diesem Computer oder ändere oben das Image.",
