trace_title: "Messen, wie es spielt",
trace_measuring: "Misst",
trace_what: "Für ein LZ4-Spiel-Image, das so lädt, wie das Spiel spielt. Eine Mess-Version von ampr_emu zeichnet jede Datei auf, die das Spiel beim Spielen liest; ein daraus gebautes Profil wählt Blockgrößen, Layouts und Cache-Größen pro Datei statt einer Schätzung für alle. Convert nutzt es, wenn du ein LZ4-Image dieses Spiels machst.",
