"collection.copy_all_links": "Alle Links kopieren",
"collection.copy_link_hint_v2": "Ein Link, über den diese PS5 das Paket selbst installieren kann (ein Browser oder ein Paket-Installer auf der Konsole). Er funktioniert, solange dieser Computer an ist, bis du ihn unter Bereitgestellt stoppst oder die App beendet wird.",
