"collection.serving_body_v2": "Pakete, die dieser Computer einer PS5 bereitstellt, die sie selbst abruft. Ein Link funktioniert für die PS5, für die er erstellt wurde (oder jedes Gerät in deinem Netzwerk, wenn du es erlaubst), bis du ihn stoppst oder die App beendet wird.",
