"collection.pick_server_folder": "Der Ordner auf {name} mit deinen Spielen",
"collection.server_folders_hint": "Ein Ordner auf einem gespeicherten Server (SMB, FTP, SFTP/WebDAV) wird an Ort und Stelle gelesen: Nichts wird auf diesen Computer kopiert, und seine Spiele installieren direkt vom Server. Aufräumen funktioniert dort ebenfalls und benennt direkt auf dem Server um; In den Papierkorb gilt nur für Ordner auf diesem Computer.",
