fs_send_route: "Läuft direkt zwischen den Konsolen, wenn sie sich erreichen, sonst über diesen Computer.",
fs_send_route_direct: "Geht direkt zwischen den Konsolen, nie über dieses Gerät; können sie sich nicht verbinden, schlägt das Senden fehl und sagt warum.",
fs_send_route_relay: "Geht über dieses Gerät.",
fs_send_route_change: "Ändern…",
