"minion_off_for_new_hint": "Verbindet sich eine Konsole zum ersten Mal mit dieser App, wird Minion dort einmal ausgeschaltet. Deine bisherigen Konsolen bleiben, wie sie sind, und schaltest du Minion auf einer Konsole wieder ein, bleibt es dort an.",
"minion_boot_helper_note": "Minion braucht den laufenden Helfer. Damit er mit der PS5 startet, schalte Payloads → Payload Manager → PS5Upload-Helfer beim Start laden ein.",
