"ps4move_title": "Spielstände von einer PS4 übertragen",
"ps4move_badge": "Experimentell",
"ps4move_experimental": "Experimentell: Das Zurückspielen von PS4-Spielständen auf eine PS5 klappt nicht immer, ein Spiel lädt sie vielleicht nicht. Probiere zuerst ein Spiel; sein PS5-Spielstand bleibt erhalten und lässt sich aus den Sicherungen des Spiels zurückholen.",
"ps4move_safety": "Die PS4 wird nur gelesen, nie verändert. Ihre Spielstände werden zuerst auf diesen Computer kopiert. Auf der PS5 werden nur die gewählten Spiele angefasst, ihr eigener Spielstand wird vorher gesichert, und sonst wird nichts (Benutzer, Systemdateien, Trophäen) verändert.",
"ps4move_need_dir": "Wähle zuerst oben unter Automatische Sicherungen einen Ordner: Dort landen die Spielstände der PS4 und jeder PS5-Spielstand, bevor er ersetzt wird.",
