"play_setup_account_body": "Spielen koppelt sich mit einer Konto-ID. Ein mit dem PlayStation Network verknüpfter Benutzer hat schon eine; ein Offline-Benutzer braucht eine: lege sie unter Konten fest (jede ID geht; notiere sie, danach erstellte Spielstände hängen daran).",
