"rp_picture_crop": "Auf 21:9 zuschneiden",
"rp_picture_crop_hint": "Schneidet oben und unten vom Bild ab, sodass es 21:9 wird. Nur für Spiele für Ultrawide-Bildschirme, die dort schwarze Balken haben: Bei allen anderen Spielen fehlt dann ein Teil des Bildes.",
"fs_rename_format": "Eigenes Format",
"fs_rename_format_hint": "Felder: {title} {titleid} {contentid} {version} {format} {platform} {name}. Modifikatoren: {title:upper}, {title:20}, {version:short}. <...> entfällt, wenn ein Wert darin fehlt. Wird auf diesem Gerät gespeichert.",
"fpkg.image.ampr_emu_build": "Emulator",
"conn_nfs_export": "Export (leer: alle)",
"conn_nfs_ids": "Benutzer- und Gruppen-ID",
"conn_nfs_ids_hint": "NFS hat keine Passwörter: Der Server vertraut diesen IDs, und der Export legt fest, wer sich verbinden darf. Als \"secure\" markierte Exporte brauchen außerdem einen Port, den nur ein Administrator öffnen kann. Markiere deinen als \"insecure\", wenn er diesen Computer ablehnt.",
"fs_rename_from_title": "Nach Titel umbenennen",
"fs_rename_no_title": "Hier stehen weder Titel noch Titel-ID, daher gibt es nichts, wonach es benannt werden könnte.",
"fs_name_too_long_smp": "{over} Bytes zu lang für ShadowMount+. Unter diesem Namen erscheint es nicht auf der Konsole.",
"fs_name_too_long_confirm": "Trotzdem umbenennen",
"fs_hide": "Vor ShadowMount+ verbergen",
"fs_unhide": "ShadowMount+ wieder zeigen",
"fs_hide_hint": "Benennt es mit einem Punkt davor um. Der Scan von ShadowMount+ überspringt das, sodass eine andere Kopie des Spiels genutzt wird.",
"fpkg.ps4_game_note_v2": "Ein PS4-Spiel. Es wird in ein PS4-Paket, ein Spiel-Image oder einen Ordner konvertiert; ein Image oder Ordner erhält die param.json, die ShadowMount+ braucht.",
"fpkg.ps4_merged_note_v2": "Das PS4-Spiel {title} mit eingefügtem Update: aus {from} wird {to}. Es wird in dieser Version zu einem PS4-Paket, einem Spiel-Image oder einem Ordner konvertiert.",
"fpkg.ps4_patch_note_v2": "Ein PS4-Update, Version {version}, für {title}. Es enthält nur die geänderten Dateien und ist allein kein Spiel: Wähle unten das Spiel, zu dem es gehört; was du erstellst, ist dann das Spiel in dieser Version.",
"fpkg.ps4_pkg.options": "Ein PS4-Paket behält die Dateien des Spiels, wie sie sind: Nichts wird komprimiert, das Spiel behält alle seine Sprachen, und jede Datei wird zurückgelesen und verglichen, bevor das Paket behalten wird.",
"fpkg.ps4_licence_note": "Ein PS4-Add-on für {title}, das nur eine Lizenz ist: Es schaltet etwas im Spiel frei und enthält keine Dateien, es gibt also nichts zu konvertieren.",
"fpkg.ps4_addon_note": "Ein PS4-Add-on für {title}. Seine Dateien werden zu einem Ordner, nicht zu einem Image oder Paket. ShadowMount+ bindet keine Add-ons ein: Sie erreichen das Spiel nur dort, wo das Spiel selbst nach ihnen sucht, etwa in einem Ordner im Spiel.",
"fpkg.merge.title_patch": "In das Spiel einfügen",
"fpkg.merge.title_game": "Ein Update in das Spiel einfügen (optional)",
"fpkg.merge.game_label": "Das Spiel, in das dieses Update gehört",
"fpkg.merge.update_label": "Ein PS4-Update für dieses Spiel",
"fpkg.merge.hint": "Ein Paket, Image oder Ordner. Das Update muss für denselben Titel und neuer als das Spiel sein.",
"fpkg.merge.browse": "Durchsuchen",
"fpkg.merge.ok": "✓ {title}: aus {from} wird {to}. Das Update ersetzt {replaced} Dateien und fügt {added} hinzu.",
"fpkg.merge.pick_game": "Wähle das PS4-Spiel, in das dieses Update gehört",
"fpkg.merge.pick_update": "Wähle ein PS4-Update für dieses Spiel",
"fpkg.image.zstd": "zstd-Asset-Packs (am kleinsten, für ShadowMount+)",
"fpkg.image.zstd_body": "Packt alles außer den Systemdateien des Spiels in zstd-Packs, direkt ins Image und ohne temporäre Kopie. Das Image erhält quer3qs ampr-emu-ng als Emulator, vor der Verwendung gegen eine veröffentlichte Prüfsumme geprüft. Ein Spiel in LZ4-Packs wird umgestellt. Schalte update_emulators in ShadowMount+ aus, sonst kann es den Emulator gegen einen tauschen, der sie nicht lesen kann.",
"fpkg.image.zstd_level": "Komprimierungsstufe",
"fpkg.image.zstd_runtime": "Pack-Laufzeit",
"fpkg.image.zstd_runtime_latest": "Neueste Version (Standard)",
"fpkg.image.zstd_runtime_pinned": "Getestet {version}",
"fpkg.image.zstd_runtime_body": "„Neueste“ verwendet das aktuelle ampr-emu-ng-Release auf GitHub nur, wenn es zur SHA-256-Prüfsumme passt, die GitHub dafür veröffentlicht; sonst oder offline kommt das getestete {version} hinein. „Getestet“ verwendet immer {version}.",
"fpkg.folder.zstd_body": "Schreibt das Spiel als normalen Ordner, alles außer den Systemdateien in zstd-Packs, mit quer3qs ampr-emu-ng als fakelib/libSceAmpr.sprx. Auch ein Spielordner kann die Quelle sein. LZ4-Packs gibt es hier nicht: Sie kommen nur in ein .exfat-Image. Schalte update_emulators in ShadowMount+ aus, sonst kann es den Emulator gegen einen tauschen, der sie nicht lesen kann.",
"ampr_emu_add_hint": "Dieses Spiel liest seine Dateien über AMPR und hat keinen Emulator. Manche solcher Spiele starten ohne ihn nicht aus einem Image, andere laufen problemlos. Fügt drakmors ampr_emu 0.4.2.1 hinzu, einmalig geladen und gegen eine bekannte Prüfsumme geprüft. Ein Image bleibt unverändert: Der Emulator kommt in einen ShadowMount+-Backport-Ordner.",
"ampr_emu_done_backport": "Als ShadowMount+-Backport in {folder} hinzugefügt. Das Image bleibt unverändert. Starte das Spiel, um es zu testen.",
"ampr_emu_done_folder": "Zum Spielordner {folder} hinzugefügt. Starte das Spiel, um es zu testen.",
"fpkg.fake_sign_note": "{count} einfache (unsignierte) ausführbare Dateien dieses Spiels werden beim Konvertieren fake-signiert, sonst würde es nicht starten. Die Quelle bleibt unverändert.",
"fpkg.image.ampr_emu": "AMPR-Emulator hinzufügen",
"fpkg.image.ampr_emu_body": "Dieses Spiel liest seine Dateien über AMPR und hat keinen Emulator. Manche solcher Spiele starten ohne ihn nicht aus einem Image, andere laufen problemlos. Fügt drakmors ampr_emu 0.4.2.1 als fakelib/libSceAmpr.sprx hinzu, einmalig vom GitHub-Release geladen und gegen eine bekannte Prüfsumme geprüft.",
"fpkg.image.lz4_placement_note": "Bewahre ein gepacktes Image im internen Speicher der Konsole auf: Von USB blieb eines laut Bericht auf einem schwarzen Bildschirm hängen. Schalte update_emulators in ShadowMount+ aus, sonst kann es den Emulator gegen einen tauschen, der keine Packs lesen kann.",
"smp_rescan": "Jetzt scannen",
"smp_rescan_done": "ShadowMount+ scannt. Neue Images werden erkannt, und Spiele, die nicht eingebunden werden konnten, werden erneut versucht.",
