"rp_err_in_use": "Ein anderes Gerät nutzt Remote Play auf dieser PS5, oder die PS5 beendet noch eine Sitzung. Schließe Remote Play auf dem anderen Gerät (die PS-Remote-Play-App, chiaki) und drücke dann Start.",
"rp_err_console_ended": "Die PS5 hat den Stream beendet: {reason}",
"rp_err_no_session": "Der Stream endete, während diese Seite weg war. Drücke Start, um weiterzuspielen.",
"rp_err_other": "Der Stream wurde beendet.",
"rp_err_lost": "Die Verbindung zur PS5 ist während des Streams abgebrochen. Starte ihn erneut; passiert das öfter, verbinde die PS5 oder dieses Gerät per Kabel.",
"rp_err_rp_off": "Remote Play ist auf der PS5 ausgeschaltet. Öffne auf der Konsole Einstellungen › System › Remote Play und schalte „Remote Play aktivieren“ ein (wenn es schon an ist, aus- und wieder einschalten), dann drücke Start. Ausgegraut? Das Konto des PS5-Benutzers muss aktiviert sein, und eine auf die sp-int-NP-Umgebung umgestellte PS5 lässt es aus: Stelle sie wieder auf np.",
"rp_err_refused": "Die PS5 hat den Start von Remote Play abgelehnt. Prüfe auf der Konsole Einstellungen › System › Remote Play › Remote Play aktivieren (aus- und wieder einschalten), drücke Zulassen unter Spielen › Einrichten oder kopple erneut. Der Code unten sagt, welche Ablehnung es war. Immer noch abgelehnt? Starte die PS5 neu: Eine Konsole, die lange läuft, kann bis zum Neustart ablehnen.",
"web_update_how_docker": "Zum Aktualisieren führe das im Ordner mit deiner Compose-Datei aus (Watchtower kann das auch für dich erledigen):",
"web_update_how_app": "Diese Seite kommt von PS5Upload auf einem anderen Computer. Aktualisiere die App dort, dann aktualisiert sich diese Seite mit.",
"rp_err_unreachable": "Die PS5 antwortet nicht im Netzwerk. Prüfe, ob sie eingeschaltet und im selben Netzwerk ist und ob Remote Play in ihren Einstellungen aktiviert ist.",
"rp_err_video": "Die PS5 hat diese Bildgröße abgelehnt. Versuche 720p.",
"rp_err_no_session_id": "Die PS5 hat den Stream angenommen, ihn aber nicht fertig gestartet. Sieh auf den Fernseher, falls die PS5 etwas fragt. Auch ein Spiel, das ein anderer PS5-Benutzer gestartet hat, kann ihn aufhalten: Wechsle zu deinem Benutzer oder schließe dieses Spiel und drücke dann Start.",
"rp_err_wake": "Die PS5 ist im Ruhemodus und ist nicht aufgewacht. Prüfe, ob sie am Strom hängt und ob unter Einstellungen › System › Energiesparen › Im Ruhemodus verfügbare Funktionen „Mit dem Internet verbunden bleiben“ und „Einschalten der PS5 über das Netzwerk aktivieren“ an sind.",
