"games_grid_description2": "Jedes deiner Spiele, jeweils einmal: deine Kopien auf diesem Computer oder einem gespeicherten Server, was die PS5 installiert hat, und die Spiele auf ihren Laufwerken. Filtere danach, was auf der PS5 ist; öffne ein Spiel für alle seine Kopien und Aktionen.",
