"rp_sound_none": "Die PS5 sendet keinen Ton an diesen Stream. Stoppe den Stream und starte ihn neu; bleibt er stumm, prüfe, wo die PS5 ihren Ton ausgibt (Einstellungen › Ton › Audioausgabe), und sende einen Fehlerbericht.",
"rp_sound_format": "Die PS5 sendet ihren Ton in einem Format, das PS5Upload noch nicht abspielen kann. Ein Fehlerbericht von jetzt verrät uns, welches.",
"rp_sound_device": "Der Ton der PS5 kommt auf diesem Gerät an, aber nichts davon wird abgespielt. Prüfe Tonausgabe und Lautstärke dieses Geräts, dann stoppe den Stream und starte ihn neu. Immer noch stumm? Sende einen Fehlerbericht.",
