"rp_keep_hint": "Andere Bildschirme lassen den Stream laufen; so lange wartet er, wenn ihn kein Fenster zeigt (geschlossen oder neu geladen), bevor er endet.",
"rp_game_mode_mac": "Während du spielst, bleiben Computer und Bildschirm wach. Vollbild schaltet außerdem den Spielmodus ein (macOS 14 und neuer).",
"rp_game_mode_ios": "Der Spielmodus schaltet sich ein, solange die App den Bildschirm füllt (iOS und iPadOS 18 und neuer).",
"rp_game_mode_windows": "Während du spielst, bleiben Computer und Bildschirm wach. Windows lässt eine App den Spielmodus nicht einschalten; siehe FAQ.",
"rp_game_mode_linux": "Während du spielst, bleiben Computer und Bildschirm wach, und GameMode (gamemoded) wird eingeschaltet, falls installiert.",
"rp_game_mode_android": "Während du spielst, bleibt der Bildschirm an, das Gerät hält wo möglich ein gleichmäßiges Tempo, und ein Fernseher an HDMI wird um seinen Spielmodus gebeten.",
"rp_set_controls": "Steuerung",
"rp_capture_pointer": "Klick ins Bild blendet den Zeiger aus",
