"rp_dualsense": "DualSense-Effekte",
"rp_dualsense_blocked": "Dieser Computer lässt die App deinen DualSense nicht öffnen, daher sind Touchpad, Bewegung und adaptive Trigger aus. In der FAQ steht die eine Zeile, die du ergänzen musst (eine udev-Regel).",
"rp_dualsense_hint": "Mit einem DualSense an diesem Computer: adaptive Trigger und, per USB angeschlossen, haptisches Feedback. Gilt ab dem nächsten Start.",
