"rp_show_here": "Hier anzeigen",
"rp_running_elsewhere_body": "Er wurde in einem anderen Fenster oder vor dem Neuladen dieser Seite gestartet und läuft noch.",
"rpg_user_title": "Einen Benutzer an der PS5 anmelden",
"rpg_user_body": "Wähle an der Konsole den Benutzer, mit dem du spielst. Niemand muss am Bildschirm bleiben, aber der Benutzer muss angemeldet sein. Hat der Benutzer einen Anmelde-Passcode, fragt Play danach, wenn du Start drückst.",
"rpg_account_title": "Diesem Benutzer eine Konto-ID geben",
"rpg_signin_title": "Das Konto beim PlayStation Network anmelden (offline)",
"rpg_service_title": "Remote Play einschalten",
"rpg_service_body": "Einstellungen › System › Remote Play › Remote Play aktivieren. Die App kann es für dich einschalten und ab Firmware 10.00 auch für diesen Benutzer erlauben. Meldet Start danach, dass Remote Play ausgeschaltet ist, schalte es in den Einstellungen der PS5 selbst ein: Es zählt der Schalter auf der Konsole.",
"rpg_rest_title": "Aufwecken der PS5 aus dem Ruhemodus erlauben",
"rpg_rest_body": "Einstellungen › System › Energiesparen › Im Ruhemodus verfügbare Funktionen: Schalte „Mit dem Internet verbunden bleiben“ und „Einschalten der PS5 über das Netzwerk aktivieren“ ein. Ohne sie lässt sich eine Konsole im Ruhemodus nicht aufwecken, und ihr Netzwerk schläft nach wenigen Sekunden ein. Nur die Konsole kann diese anzeigen.",
