"dump_decrypt_hint": "Nötig, um den Dump als Ordnerspiel zu starten oder zu backporten. Aus: eine einfache Kopie.",
"dump_decrypt_risk": "Entschlüsseln kann die Konsole einfrieren",
"dump_decrypt_risk_body": "Zum Entschlüsseln tauscht der Helfer für jede ausführbare Datei kurz einen Systemteil aus, den jedes Programm nutzt. Liest das Spiel genau dann eine Datei, kann die Konsole einfrieren und muss hart ausgeschaltet werden. Bleib währenddessen im Startbildschirm des Spiels. Nur Firmware bis 13.60; auf neuerer Firmware ist der Dump eine einfache Kopie.",
