"rp_picture_here": "Bild auf diesem Gerät",
"rp_picture_here_hint": "Aus: Neue Streams starten hier ohne Bild, Ton und Controller. Das schont CPU und Akku dieses Geräts. Freunde in Play Together und Go live bekommen den Stream weiterhin, und du kannst es im Stream jederzeit wieder einschalten.",
"rp_picture_off_title": "Das Bild ist auf diesem Gerät aus",
"rp_picture_off_body": "Der Stream läuft für deine Freunde und deine Übertragung weiter. Auch Ton und Controller sind hier aus, dieses Gerät hat also kaum etwas zu tun.",
"rp_picture_turn_on": "Bild einschalten",
"rp_picture_turn_off": "Bild auf diesem Gerät ausschalten",
"golive_picture_hint": "Aus: Dieser Computer leitet den Stream weiter, ohne ihn zu dekodieren oder anzuzeigen. Das spart CPU und Wärme. Lass die App laufen; die Steuerung bleibt hier.",
"pt_picture_hint": "Aus: Dieses Gerät lädt nur deine Freunde ein. Kein Bild, Ton oder Controller hier, und das Spiel deiner Freunde läuft weiter. Zum Spielen am Fernseher.",
"pt_tv_title": "Spielst du am Fernseher?",
"pt_tv_note": "Dieser Stream ist mit dem PS5-Benutzer angemeldet, den du mit PS5Upload gekoppelt hast. Drücke PS am DualSense der Konsole und wähle einen anderen Benutzer: Das bist du am Fernseher. Wählst du den Benutzer des Streams, endet der Stream für alle, auch für deine Freunde. Manche Spiele zählen den Benutzer des Streams ebenfalls als Spieler, sodass ein Platz weniger für Freunde bleiben kann.",
"pt_tv_seats": "Eine PS5 nimmt 4 Controller. Mit deinem DualSense am Fernseher nutzt der erste Freund den Controller des Streams und spielt als dessen Benutzer, ohne einen Benutzer zu wählen, und 2 weitere bekommen je einen eigenen Controller: Platz für 3 Freunde.",
"pt_stream_seat_note": "Ein Freund nutzt den Controller dieses Streams, daher spielt dein Controller hier erst wieder, wenn er geht.",
