"send_title_v2": "Hochladen & installieren",
"collection.send_many_body_v2": "Jede PS5 bekommt, was ihr fehlt: das Paket des Spiels oder seinen Ordner, sein Image oder Archiv, dazu neuere Updates und DLC für die Spiele, die sie hat. Pakete werden von diesem Computer gestreamt; der Rest wird auf das in „Hochladen & installieren“ eingestellte Laufwerk hochgeladen, in den homebrew-Ordner.",
"first_run_step4_body_v3": "Stecke einen USB-Stick mit .ffpkg-Spiel-Images in deine PS5, und ShadowMount+ hängt sie automatisch ein — sie erscheinen unter Spiele. Um andere Dateien zu senden oder .pkg-Pakete zu installieren, nutze „Hochladen & installieren“.",
"first_run_go_upload_v2": "„Hochladen & installieren“ öffnen",
"fpkg.aboutFake_v2": "Das Ergebnis ist ein Fake-Paket, daher braucht die Konsole geladene Fake-Paket-Unterstützung, bevor sie es installiert: kstuff (die Version mit PS5-Fake-Paket-Unterstützung), a53_ppr_install_fast.elf und shadowmountplus.elf, in dieser Reihenfolge. „Hochladen & installieren“ sagt dasselbe neben seinen Installieren-Schaltflächen.",
"fpkg.openUpload_v2": "„Hochladen & installieren“ öffnen",
"netdoctor.speed_cap.on.fix_v2": "Entferne das Limit in „Hochladen & installieren“, wenn du es nicht brauchst.",
"payloads_fpkg_ppr_note_v2": "Für Fake-Pakete braucht es außerdem a53_ppr_install_fast.elf, das nicht in dieser Liste steht: Es gibt keinen fertigen Download, es wird aus dem Quellcode auf GitHub gebaut. „Hochladen & installieren“ nennt alles, was Fake-Pakete brauchen, in der richtigen Reihenfolge.",
"fs_extract_next_pkgs_v2": "Es enthält {n} Paket(e): Installiere sie über „Hochladen & installieren“ oder über ihre Zeile hier.",
"game_hub_no_addons_v2": "Für diesen Titel sind keine DLC-Pakete abgelegt. Sende eines über „Hochladen & installieren“.",
"game_hub_open_install_v2": "„Hochladen & installieren“ öffnen",
"bandwidth_cap_off_hint_v3": "Kein Limit. Setze eines, wenn Uploads dein WLAN/LAN auslasten und andere Geräte ruckeln. Es gilt ab dem nächsten gestarteten für jeden Upload, aus „Hochladen & installieren“, der Warteschlange und Dateien.",
"game_hub_no_updates_v2": "Für diesen Titel sind keine Update-Pakete abgelegt. Sende eines über „Hochladen & installieren“.",
"pkglib.fpkgsupport.firmware": "PS5-Fake-Pakete (PS5 FPKG) werden auf Firmware neuer als 11.60 noch nicht unterstützt: Sie lassen sich installieren, aber das Spiel startet nicht. PS4-Fake-Pakete funktionieren.",
"upload_drop_here3": "Pakete, Spiele, Disk-Images, Archive oder beliebige Dateien ablegen oder auswählen",
"upload_pick_here_mobile3": "Pakete, Spiele, Disk-Images, Archive oder beliebige Dateien auswählen",
"upload_drop_kind_pkg": "Pakete (.pkg, .fpkg): als Spiel, Update oder DLC installiert, von hier gestreamt oder zuerst hochgeladen.",
"upload_drop_kind_game": "Spielordner und Spiel-Dumps: auf die PS5 kopiert; sie können auf den Startbildschirm.",
"upload_drop_kind_image": "Disk-Images (.exfat, .ffpkg, .ffpfs, .ffpfsc): auf die PS5 kopiert; sie lassen sich mounten.",
"upload_drop_kind_archive": "Archive (.zip, .7z, .rar, .tar, .tar.zst, .tar.gz, .tar.xz, .tar.bz2, .zst): auf der PS5 entpackt oder unverändert gesendet — du entscheidest.",
"upload_drop_kind_other": "Jede andere Datei oder jeder andere Ordner: unverändert kopiert.",
"upload_other_ways": "Oder ein Paket installieren:",
"queue_stream_fail_hint": "Bei „Streamen & installieren“ holt die PS5 das Paket von diesem Computer. Schlägt es weiterhin fehl, lass ps5upload in der Firewall dieses Computers im lokalen Netzwerk zu, damit die PS5 ihn erreicht, oder nutze „Per Upload erneut versuchen“: Das Paket wird zuerst auf die PS5 kopiert und dann installiert.",
"err_install_enoent_generic_v2": "Sonys Installer konnte eine während der Installation benötigte Datei nicht öffnen (Kernel-Fehler 0x80020002 = ENOENT). Handelt es sich um eine DLC-pkg, ist das Basisspiel noch nicht installiert — installiere zuerst die Basis. Andernfalls wurde das bereitgestellte Paket möglicherweise zwischen Upload und Installation gelöscht; versuche die Installation einmal erneut. Schlägt sie weiterhin fehl, installiere es mit „Streamen & installieren“ unter „Hochladen & installieren“: Das Paket wird dann direkt von diesem Computer gesendet, statt zuerst auf die Konsole kopiert zu werden.",
"err_display_crashed": "Die Anzeige der App hatte dabei einen Fehler (React #185) und verfolgt die Übertragung nicht mehr, die trotzdem fertig sein kann. Prüfe die PS5 oder tippe auf Wiederholen. Ein Fehlerbericht hilft uns jetzt.",
"upload_convert_first": "Zuerst konvertieren",
"batch_convert_first_hint": "Die markierten Spiele, Ordner und Images in der Werkstatt öffnen, um daraus zuerst Pakete, Images oder Ordner zu machen",
"add_sources_pick_folders": "Einen oder mehrere Ordner wählen",
"add_sources_pick_files": "Eine oder mehrere Dateien wählen",
"workshop_add_hint": "Wähle ein Spiel, um es hier zu prüfen. Mehrere Spiele oder ein Ordner mit Spielen kommen in die Warteschlange und werden nacheinander erstellt.",
"cq_title_v2": "⑤ Warteschlange",
"cq_about": "Nacheinander auf diesem Computer erstellt, jedes so, wie ②, ③ und ④ beim Hinzufügen eingestellt waren. Füge unter ① weitere hinzu, auch während die Warteschlange läuft; ein wartendes Spiel änderst du über seine Optionen-Schaltfläche.",
"cq_then_send": "Ein Spiel, das installiert oder hochgeladen werden soll, kommt nach dem Erstellen in die Warteschlange von {send}.",
"cq_open_send": "{send} öffnen",
"backup_alike_toggle": "{count} gleiche Kopien seit {since}. Einzeln anzeigen, um eine ältere wiederherzustellen.",
"add_sources_no_picker": "Dieser Build kann diesen Rechner nicht durchsuchen — gib einen Pfad ein, den die Engine sieht.",
"collection.empty_body_v2": "Pakete, Spielordner, Spiel-Images und Archive darin werden gefunden und nach Spiel gruppiert. Im Ordner wird nichts verändert. Ein Ordner auf diesem Gerät, ein externes Laufwerk oder ein Ordner auf einem NAS oder Server (SMB, FTP, SFTP, WebDAV) funktionieren.",
"collection.add_nas_folder": "Von einem NAS oder Server",
"browse_this_device": "Dieses Gerät…",
"browse_this_device_hint": "Liest von dem Gerät, auf dem dieser Browser läuft. Es wird zweimal kopiert, erst auf den Server, dann auf die PS5: langsamer, und der Server braucht freien Platz für die Kopie.",
"browse_on_server": "Auf dem Server…",
"browse_on_server_hint": "Liest von {host}, dem Computer, auf dem die Engine läuft. Am schnellsten: Es geht direkt auf die PS5.",
"browse_choose_source": "Wählen, wovon gelesen wird",
"queue_added_waits_for_start": "Zur Warteschlange hinzugefügt – drücke „Warteschlange starten“, um sie auszuführen",
"queue_added_waits_for_start_body": "„Warteschlange beim Hinzufügen starten“ ist aus, daher startet nichts, bis du „Warteschlange starten“ drückst.",
"queue_auto_start": "Warteschlange beim Hinzufügen starten",
"queue_auto_start_tooltip": "An: „Installieren“, „Jetzt hochladen“ und „Senden“ starten die gesamte Warteschlange dieser Konsole der Reihe nach. Aus: Sie fügen nur zur Warteschlange hinzu, und nichts läuft, bis du „Warteschlange starten“ drückst.",
"queue_auto_start_hint": "An: „Installieren“, „Jetzt hochladen“ und „Senden“ starten die gesamte Warteschlange der Konsole der Reihe nach – nicht nur das gerade Hinzugefügte. Aus: Sie fügen nur zur Warteschlange hinzu, und nichts läuft, bis du „Warteschlange starten“ drückst. Standardmäßig an.",
"queue_start_rest_tooltip": "Nur die von dir gestarteten Einträge laufen. Damit läuft auch alles Wartende, in der Reihenfolge der Warteschlange.",
"queue_start_v2": "Warteschlange starten",
"queue_stop_v2": "Warteschlange stoppen",
"upload_starts_queue": "Startet die Warteschlange: Bereits Wartendes kommt zuerst, der Reihe nach",
"upload_waits_for_start": "Fügt zur Warteschlange hinzu. Läuft, wenn du „Warteschlange starten“ drückst („Warteschlange beim Hinzufügen starten“ ist aus)",
"rp_touch_size": "Controller-Größe",
