"rp_touch_mode_switch_full_hint": "Er blendet sich mit den Stream-Steuerelementen aus; tippe auf das Bild, um ihn zurückzuholen.",
"rp_menu": "Menü",
"rp_menu_close": "Menü schließen",
"rp_more": "Mehr",
"rp_view_only": "Hier nur zum Ansehen. Tippe auf Vollbild, um mit dem Bildschirm-Controller zu spielen. Ein an dieses Gerät angeschlossener Controller oder eine Tastatur spielt auch hier.",
"rp_touch_hint": "Dreh das Telefon quer oder tippe auf „Vollbild“, um den Bildschirm zu füllen. Dort öffnet das kleine ⋯ oben das Menü; Tippen auf das Bild ist Spieleingabe und verlässt das Vollbild nie. „Zurück“ verlässt das Vollbild.",
