helper_copy_place_etahen: "etaHEN-Payloads",
helper_copy_place_autoloader: "Autoloader",
helper_boot_label: "PS5Upload-Helfer beim Start laden",
helper_boot_hint: "Payload Manager startet den Helfer nach allem, was in seiner Startliste davor steht, sodass Minion und diese App nach einem Neustart ohne PC funktionieren. Bei jeder Verbindung bringt diese App die Kopie auf ihren eigenen Helfer und behält die vorherige; startet eine neue Kopie nach einem Neustart nicht, kommt die vorherige zurück.",
helper_boot_list_off: "Die Startliste von Payload Manager ist oben ausgeschaltet, daher startet beim Hochfahren nichts, bis du sie einschaltest.",
helper_boot_list_off_title: "Die Startliste von Payload Manager ist aus",
helper_boot_list_off_confirm: "Solange die Startliste aus ist, startet Payload Manager beim Hochfahren nichts, auch den Helfer nicht. Einschalten?",
helper_boot_turn_on_list: "Startliste einschalten",
helper_boot_not_listed: "Der Helfer ist gespeichert, steht aber nicht in der Startliste von Payload Manager. Diese App trägt ihn bei der nächsten Verbindung wieder ein.",
helper_boot_bad_version: "Helfer {version} ist auf dieser PS5 beim Start nicht hochgekommen, daher wurde die vorherige Kopie zurückgelegt. Eine neuere App-Version versucht es erneut.",
helper_boot_needs_pm: "Den PS5Upload-Helfer beim Start zu laden braucht Payload Manager: Er startet den Helfer, wenn die PS5 hochfährt.",
helper_boot_failed: "Konnte nicht ändern, ob der Helfer beim Start geladen wird",
helper_boot_on_title: "Der Helfer wird jetzt beim Start geladen",
helper_boot_restored_title: "Der Helfer ist beim Start nicht hochgekommen",
helper_boot_restored_body: "Die PS5 wurde neu gestartet, aber Helfer {version} aus Payload Manager ist nicht hochgekommen, daher hat diese App einen gesendet. Die vorherige Kopie ist wieder in Payload Manager und startet beim nächsten Neustart. Diese App legt {version} dort nicht noch einmal ab.",
helper_copies_updated_title: "Helfer aktualisiert",
helper_copies_updated_body: "Deine PS5 startet beim nächsten Neustart den Helfer {version}.",
helper_copies_failed_title: "Der Helfer, den deine PS5 beim Start lädt, konnte nicht aktualisiert werden",
helper_copies_failed_body: "Weiterhin der alte Helfer: {list}. Die PS5 startet ihn nach jedem Neustart wieder. Zum Beheben von Hand lade ps5upload.elf {version} von der Releases-Seite herunter und kopiere sie über diese Datei (Dateien-Bildschirm, FTP oder das USB-Laufwerk), oder lade sie im Payload Manager unter demselben Namen erneut hoch. ({error})",
helper_mismatch_boot_copy: "Deine PS5 hat eine ältere Kopie des Helfers gestartet, die sie für den Start aufbewahrt ({list}). Drücke „Helfer senden“: Diese App sendet den passenden Helfer und aktualisiert auch diese Kopie, sodass die PS5 nach einem Neustart den neuen startet.",
