  "rp_codec_hdr": "HDR (HEVC, experimentell)",
  "rp_codec_hdr_hint": "Die PS5 sendet HDR; auf diesem Bildschirm wird es in HDR angezeigt. Experimentell: Wirkt das Bild matt oder zu hell, wechsle zurück zu Automatisch.",
