  "hush_hold_session": "Die ganze Sitzung",
  "hush_rp_note": "Remote Play nutzt denselben Video-Encoder, daher hat ein Stream kein Bild, solange Hush ihn blockiert. Mit hold_s wartet Spielen vor dem Start, bis die Sperre endet. Sonst pausiert es Hush für einen Stream, wenn du es willst, und schaltet es danach wieder ein.",
  "hush_log": "log.txt, neueste zuletzt",
  "hush_log_empty": "Noch nichts protokolliert.",
  "rp_blocker_hush_reason": "Hush ist an. Es blockiert das Bild von Remote Play.",
  "rp_blocker_hush_leftover_reload": "Hush ist beendet, aber seine Sperre des Video-Encoders besteht noch, daher hat Remote Play kein Bild. Sende Hush noch einmal an die PS5: Es hebt die zurückgelassene Sperre auf.",
  "rp_blocker_hush_leftover_restart": "Hush ist beendet, aber seine Sperre des Video-Encoders besteht noch, daher hat Remote Play kein Bild. Starte die PS5 neu, um sie aufzuheben.",
  "rp_blocker_stuck_title": "{name} hat Remote Play ohne Bild zurückgelassen",
  "rp_blocker_pause": "{name} pausieren, während ich spiele",
  "rp_blocker_anyway": "Trotzdem starten",
  "rp_blocker_body": "{name} schaltet den Video-Encoder der Konsole ab, und Remote Play braucht ihn. Pausiert geht {name} wieder an, wenn der Stream endet.",
  "rp_blocker_always": "Hush für Remote Play immer pausieren",
  "rp_blocker_always_hint": "Hush schaltet den Video-Encoder ab, den Remote Play braucht. Ist das an, pausiert Spielen es vor einem Stream (etwa 20 s) und schaltet es danach ohne Nachfrage wieder ein.",
