mcp_phone_title: "Richte das am Computer ein",
mcp_phone_body: "Die Engine in dieser Handy-App ist nur für die App selbst da. Agents und Skripte laufen auf einem Computer mit geöffneter PS5Upload-App oder mit der Docker-Engine.",
mcp_other_computer_title: "Diese Engine läuft auf einem anderen Computer",
mcp_other_computer_body: "Ein Agent auf diesem Computer kann diese Schritte mit dessen eigener Adresse 127.0.0.1 nutzen. Ein Agent auf einem anderen Gerät muss außerdem mit seiner Adresse in der Engine-Einstellung PS5UPLOAD_ALLOW_IP stehen.",
mcp_intro: "Mit MCP steuert ein KI-Agent deine PS5 über Tools, die er versteht: Dateien senden, Spiele installieren, Temperaturen prüfen und mehr. Einmal hinzufügen, danach einfach fragen.",
mcp_address: "MCP-Adresse",
mcp_agents_title: "Zu deinem Agent hinzufügen",
mcp_check_again: "Erneut prüfen",
mcp_after_adding: "Starte in deinem Agent eine neue Sitzung, damit er es lädt. Lass PS5Upload geöffnet, solange der Agent arbeitet: Der MCP-Server gehört zur Engine der App.",
mcp_update_title: "Auf dem neuesten Stand halten",
mcp_update_app: "Wenn PS5Upload aktualisiert wird, musst du hier nichts tun. Agents bekommen ihre Tools von der Engine, neue erscheinen also, sobald du die nächste Sitzung startest. Eine bereits offene Sitzung behält die alte Liste.",
mcp_update_address: "Ändert sich die Adresse der Engine, sagt dir die App das beim Start, und die Karte des Agents zeigt hier Aktualisieren. Ein Klick behebt es.",
mcp_update_by_hand: "Die App sieht Gemini CLI, Cursor, Claude Desktop und deine eigenen Skripte nicht. Wenn sich die Adresse hier ändert oder eines davon nach einem Update keine Verbindung mehr bekommt, kopiere die Einrichtung erneut aus Andere Agents und Apps.",
mcp_update_version: "Diese Engine hat Version {version}. Um zu sehen, womit ein Agent verbunden ist, frag ihn nach der Version der PS5Upload-Engine.",
mcp_bridge_body: "Er startet das Bridge-Programm der Engine, statt diese Adresse zu nutzen. Das funktioniert auch. Aktualisieren stellt ihn auf die Adresse um.",
mcp_stale_toast: "Ein Agent hat noch die alte Adresse der Engine und kann sich deshalb nicht verbinden. Aktualisiere ihn unter MCP & API.",
mcp_stale_open: "Öffnen",
mcp_try_title: "Dann frag zum Beispiel",
mcp_try_status: "Wie heiß ist meine PS5 gerade?",
mcp_try_space: "Was belegt auf meiner PS5 den meisten Speicherplatz?",
mcp_try_install: "Installiere dieses Paket auf meiner PS5 und sag mir Bescheid, wenn es fertig ist.",
mcp_safety_title: "Ein Agent darf alles, was du auch darfst",
mcp_safety_body: "Es gibt kein Passwort, und er kann Dateien auf deiner Konsole löschen. Lass Tools, die etwas ändern, in deinem Agent auf \"ask\" und lies jeden Konsolenbefehl, bevor du ihn erlaubst.",
mcp_safety_read_only: "Damit er nur lesen darf, setze das in der Umgebung der Engine und starte sie neu:",
mcp_access_label: "Agenten dürfen etwas ändern",
mcp_access_hint: "Aus: Agenten können nur nachsehen, etwa Dateien auflisten, den Status lesen und Übertragungen verfolgen. Nichts wird geändert.",
mcp_access_locked: "Aus, durch die Umgebung der Engine festgelegt.",
