mcp_access_limit: "Das hält Agenten von den Werkzeugen von PS5Upload fern; ein Programm, das auf diesem Computer Befehle ausführen kann, erreicht die Engine trotzdem.",
mcp_other_clients_title: "Andere Agents und Apps",
