cb_why_saves: "Alle Spielstände aller Nutzer. Sie lassen sich nur auf dieser PS5 öffnen und können so nicht auf eine andere Konsole übertragen werden.",
cb_why_captures: "Deine Fotos und Videos. Nach einer Wiederherstellung sind sie hier wieder in Screenshots & Clips, aber die Medienübersicht der PS5 zeigt sie eventuell nicht an.",
cb_why_settings: "Einstellungen für etaHEN, ShadowMount+, den Autoloader und den Payload Manager. Klein und der schnellste Weg, dein Setup zurückzubekommen.",
