cb_left_out_games: "Installierte Spiele und Updates: Sie zurückzukopieren installiert sie nicht. Behalte stattdessen deine Pakete und installiere sie neu.",
cb_left_out_system: "/system_data (Datenbank, Konten und Einstellungen der Konsole): Eine alte Kopie zurückzuspielen kann verhindern, dass die PS5 startet. Deshalb schreibt die App dort nie.",
