cb_users_title: "Wessen Spielstände wohin gehen",
cb_users_hint: "Eine zurückgesetzte PS5 hat neue Nutzer, auch bei gleichen Namen. Ein Spielstand passt nur in den eigenen Spielstand des Nutzers für das Spiel. Starte also jedes Spiel einmal als dieser Nutzer und speichere zuerst.",
