cb_title: "Backup & Wiederherstellung",
cb_desc: "Bewahre auf diesem Computer, was wichtig ist, und hol es nach einem Reset zurück.",
cb_no_console: "Verbinde dich zuerst mit einer PS5.",
cb_step_restart: "Neu starten und erneut in den abgesicherten Modus",
cb_step_restart_body: "Der abgesicherte Modus zeigt manchmal nur die letzte Option, PS5 zurücksetzen (Systemsoftware neu installieren). Laut Berichten kommen die anderen Optionen zurück, wenn du PS5 neu starten wählst und noch einmal in den abgesicherten Modus gehst. Probiere das zuerst.",
cb_step_repair: "Konsolenspeicher reparieren",
cb_step_repair_body: "Prüft das Laufwerk und repariert es. Es wird nichts gelöscht, daher ist das die erste echte Option.",
cb_step_rebuild: "Cache leeren und Datenbank neu erstellen",
cb_step_rebuild_body: "Erstellt die Inhaltsliste der Konsole neu. Spiele und Spielstände bleiben erhalten. Auf einer gejailbreakten Konsole müssen von Hand registrierte Spiele und Apps eventuell neu registriert werden. Manche berichten, dass das gereicht hat, bestätigt haben wir das aber nicht.",
cb_step_defaults: "Standardeinstellungen wiederherstellen",
cb_step_defaults_body: "Setzt die Einstellungen auf den Standard zurück. Spiele und Spielstände bleiben erhalten.",
cb_step_reset: "PS5 zurücksetzen",
cb_step_reset_body: "Löscht Nutzer, Spiele und Spielstände. Die installierte Systemsoftware bleibt unberührt, deine Firmware ändert sich also nicht und du brauchst keinen USB-Stick. Wenn die Optionen oben nicht geholfen haben, nimm diese.",
cb_step_reinstall: "PS5 zurücksetzen (Systemsoftware neu installieren)",
cb_step_reinstall_body: "Die letzte Möglichkeit: Sie entfernt auch die Systemsoftware und braucht eine Neuinstallationsdatei auf einem USB-Stick. Sonys Seite bietet nur die neueste Version an, die Datei aktualisiert also deine Firmware und kann deinen Jailbreak beenden.",
cb_usb_format: "Formatiere den Stick mit FAT32 oder exFAT.",
cb_usb_folders: "Lege einen Ordner namens PS5 an und darin einen Ordner namens UPDATE, in Großbuchstaben.",
cb_usb_file: "Speichere die Datei dort als PS5UPDATE.PUP. Es muss die Neuinstallationsdatei sein, die viel größer ist als die Update-Datei.",
cb_usb_refused: "Wenn die PS5 die Datei weiterhin nicht findet, prüfe diese drei Punkte und probiere dann einen anderen Stick: Manche funktionieren nicht.",
cb_after_offline: "Richte die PS5 ein, ohne sie mit dem Internet zu verbinden, und lehne angebotene Systemupdates ab. Ein Update kann deinen Jailbreak beenden.",
cb_after_user: "Lege deine Nutzer neu an. Unter Konten stehen die Schritte, um einem neuen Nutzer seine alte Konto-ID zu geben.",
cb_after_jailbreak: "Jailbreake die Konsole erneut und sende den Helper, öffne dann diesen Bereich und spiele dein Backup zurück.",
cb_enter_title: "So kommst du in den abgesicherten Modus",
cb_enter_body: "Schalte die PS5 aus. Halte die Ein-/Aus-Taste gedrückt, bis du den zweiten Piepton hörst (etwa sieben Sekunden). Verbinde den Controller per USB-Kabel und drücke die PS-Taste.",
cb_steps_title: "Das solltest du in dieser Reihenfolge probieren",
cb_steps_hint: "Jeder Schritt kostet mehr als der vorherige. Hör auf, sobald die PS5 startet.",
cb_erases: "Löscht deine Daten",
cb_sony_link: "Sonys Seite zum abgesicherten Modus",
cb_usb_title: "Wenn du den USB-Stick brauchst",
