"pairing_closed_body_v4": "Diese PS5 fragt nach, bevor sich ein neues Gerät verbindet, und zeigt dieses jetzt als anfragend an. Drücke auf einem Gerät, das diese PS5 schon nutzt (Verbindung), oder auf der eigenen Seite der PS5 (Einstellungen › Geräte) auf Erlauben: Diese App kommt dann von selbst herein. Oder drücke „Helfer erneut senden“, das lässt diese App herein.",
