"cw_tn_sign_out_confirm": "Diese PS5 von Tailscale abmelden? Sie vergisst die Anmeldung: Du musst dich neu anmelden, und sie bekommt eventuell eine neue Adresse. Um nur eine Weile anzuhalten, schalte sie stattdessen aus.",
"cw_tn_sub": "Spiele auf dieser PS5 von überall über dein Tailscale-Netzwerk. Auf diesem Weg erreichen nur Remote Play und PS5Upload sie. Du kannst das auch in der PS5Upload-App einrichten: Verbindung › Tailscale für diese PS5.",
