"settings_ps5_picker_hint": "Diese Einstellungen gelten nur für diese PS5. Jede deiner Konsolen hat ihre eigenen, und sie folgen ihr auf deine anderen Geräte.",
"auto_bringup_hint_ps5": "Wenn der Loader dieser PS5 (elfldr, Port 9021) läuft und der Helfer nicht, führt die App das schnelle Bring-up von selbst aus: zuerst die Bring-up-Playlist dieser PS5, falls du eine gesetzt hast, dann den Helfer, dann deine Auto-Loader-Playlist. Einmal bei jedem Start dieser PS5; nach dem Ruhemodus wird nur der Helfer erneut gesendet. Nach dem Erscheinen des Loaders wartet sie etwa 90 Sekunden, damit der eigene Autoloader der Konsole zuerst fertig wird. Standardmäßig aus.",
"bringup_playlist_label_ps5": "Bring-up-Playlist für diese PS5 (Kernel R/W, SMP)",
"bringup_playlist_hint_ps5": "Läuft beim schnellen Bring-up vor dem Helfer. Payloads hängen von der Firmware ab, daher hat jede PS5 ihre eigene. Playlists erstellst du unter Payloads.",
"upload_auto_redeploy_on_wake_hint_ps5": "Wenn der Helfer dieser PS5 offline geht (Ruhemodus, WLAN-Wechsel oder Payload-Absturz), wird im Hintergrund immer wieder versucht, ihn neu zu senden, sodass Helfer, Lüfterschwelle dieser PS5 und Upload-Port von selbst zurückkommen, sobald sie wieder erreichbar ist. Standardmäßig an.",
"keep_ps5_awake_mode_hint_ps5": "Setzt den Auto-Standby-Timer dieser PS5 zurück, damit sie nicht in den Ruhemodus geht. „Beim Hochladen und Installieren“ schützt lange Uploads (eine häufige Ursache für fehlgeschlagene Uploads; Standard). „Immer solange verbunden“ hält diese PS5 aus dem Ruhemodus, solange ihr Helfer läuft und die App offen ist. Die PS5 selbst in den Ruhemodus zu versetzen klappt in jedem Modus.",
"upload_rest_after_hint_ps5": "Wenn die Upload-Warteschlange dieser PS5 fertig ist, sie in den Ruhemodus schicken – praktisch für eine Warteschlange über Nacht. Nur wenn mindestens ein Upload geklappt hat (nicht nach Stopp oder wenn alles fehlschlug). Standardmäßig aus. Manche Firmware verweigert den Ruhemodus; du bekommst einen Hinweis, wenn diese PS5 das tut.",
"upload_wake_for_uploads_hint_ps5": "Wenn ein Upload auf diese PS5 im Ruhemodus wartet, ein Wecksignal senden und weitermachen, sobald ihr Helfer zurück ist. Dafür muss das Wecken für diese PS5 auf dem Bildschirm „Verbindung“ eingerichtet sein. Standardmäßig an.",
"install_path_fallback_hint_ps5": "Ein letzter Ausweg für ein Paket, das schon auf dieser PS5 liegt, wenn sie es aus ihrem eigenen Speicher ablehnt und es auch nicht von diesem Computer holen kann. Nur für ein Basisspiel, das nicht installiert ist, es kann also nichts entfernen. Unerprobt: Auf Firmware 11.20 hat es geklappt, auf 13.60 wird es abgelehnt, daher wird es für jede PS5 einzeln gesetzt. Wenn du es ausprobierst, melde bitte, ob es geklappt hat.",
